function OverseaRenovaInventoryPopup:__init()
end

function OverseaRenovaInventoryPopup:Awake()
    self:AddUIClick()
    self:InitEnv()
end

function OverseaRenovaInventoryPopup:InitEnv()
    self.priceEnv = {}
    for i = 1, 2 do
        local go = self["Number"..i]
        if go then
            local env = CfUtils.GetLuaScr(go,CurryEnvPath)
            if env then
                self.priceEnv[i] = env
            end
        end
    end

    if self.OriginalPrice then
        local env = CfUtils.GetLuaScr(self.OriginalPrice,CurryEnvPath)
        if env then
            self.originalEnv = env
        end
    end
end

function OverseaRenovaInventoryPopup:AddUIClick()
    SetButtonAction(self.BtnClose.gameObject,Bind(self,self.OnBtnCloseClick))
    SetButtonAction(self.FontStyleButton.gameObject,Bind(self,self.OnBtnBuyClick))
end

