function OverseaRenovaInventoryPopup:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self.parameters = self.controller.Argument.parameters
            self:InitData(self.parameters.data)
        end)
    end))
    return coWait
end

function OverseaRenovaInventoryPopup:InitData(data)
    self.allData = {}
    if not isNull(self.parameters.suitVo) then
        for i, v in pairs(data) do
            table.insert(self.allData,{isDisCount = true,data = v,isCanDoSelect = false})
        end
        self:SortData()
    else
        for i, v in pairs(data) do
            table.insert(self.allData,{isDisCount = false,data = v,isCanDoSelect = true,isSelect = true})
        end
        self:SortData()
        self:CalculationDisCount()
    end
end

function OverseaRenovaInventoryPopup:SortData()
    table.sort(self.allData,function(a,b)
        local aIsHave = component:IsHaveRenovated(a.data.refId) and 1 or 0
        local bIsHave = component:IsHaveRenovated(b.data.refId) and 1 or 0
        if aIsHave == bIsHave then
            return a.data.furnitureType < b.data.furnitureType
        else
            return aIsHave < bIsHave
        end
    end)
end

function OverseaRenovaInventoryPopup:CalculationDisCount()
    ---收集一下  一共有多少个套装
    local suidData = {}
    for i, v in pairs(self.allData) do
        local data = v.data
        if data.suitId > 0 and v.isSelect then
            if not suidData[data.suitId] then
                suidData[data.suitId] = {}
            end
            table.insert(suidData[data.suitId],data)
        end
    end
    ---当前套装是否享受折扣价
    local disCountData = {}
    for k, v in pairs(suidData) do
        local needCount = component:GetSuitNeedCount(k)
        local buyCount = 0
        for i, j in pairs(v) do
            local isHave = component:IsHaveRenovated(j)
            if not isHave then
                buyCount = buyCount + 1
            end
        end
        disCountData[k] = needCount == buyCount and true or false
    end
    for i, v in pairs(self.allData) do
        v.isDisCount = disCountData[v.data.suitId] or false
    end
end

function OverseaRenovaInventoryPopup:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
            self:Delete()
            self = nil --lua层的gc需要    
        end)
    end))
    return coWait
end

function OverseaRenovaInventoryPopup:__delete()
