end

function OverseaRenovaInventoryPopup:RefreshShow()
    if self.parameters.suitVo then
        CfUtils.FillText(self.TextDesc,localize("_name_包含以下部件:",{_name_ = self.parameters.suitVo.name}))
    else
        CfUtils.FillText(self.TextDesc,localize("一次性买齐一套家具,可享受<color=#FE23C6><size=50>套装</size></color>优惠"))
    end
    self:RefreshGridShow()
    self:RefreshPriceShow()
end

function OverseaRenovaInventoryPopup:RefreshPriceShow()
    local priceData = {}
    local originalData = {}
    for i, v in pairs(self.allData) do
        local goodsId = v.data.goodsId
        ----不能取消勾选的
        if not v.isCanDoSelect then
            local isHave = component:IsHaveRenovated(v.data.refId)
            if not isHave then
                if not priceData[goodsId] then
                    priceData[goodsId] = 0
                end
                if v.isDisCount and not originalData[goodsId] then
                    originalData[goodsId] = 0
                end
                local price = v.isDisCount and v.data.goodsNum or v.data.originalNum
                priceData[goodsId] = priceData[goodsId] + price
                if v.isDisCount then
                    originalData[goodsId] = originalData[goodsId] + v.data.originalNum
                end
            end
        else
            ---取消勾选的
            local isHave = component:IsHaveRenovated(v.data.refId)
            if not isHave then
                if not priceData[goodsId] then
                    priceData[goodsId] = 0
                end
                if v.isSelect then
                    local price = v.isDisCount and v.data.goodsNum or v.data.originalNum
                    priceData[goodsId] = priceData[goodsId] + price
                end
            end
        end
    end
    ---用来做购买计算
    self.constData = {}
    CfUtils.SetActive(self.OriginalPrice.gameObject,false)
    ---用来做显示  如果是套装 需要有原价
    if table.count(originalData) > 0 then
        CfUtils.SetActive(self.OriginalPrice.gameObject,true)
        local tempData = {}
        for i, v in pairs(originalData) do
            table.insert(tempData,{goodsId = i,num = v})
        end
        ---原价肯定只会有一个
        self.originalEnv:SetCurrencyShow(tempData[1].goodsId,tempData[1].num)
    end

    for i, v in pairs(priceData) do
        table.insert(self.constData,{goodsId = i,num = v})
    end
    for i, v in pairs(self.priceEnv) do
        if self.constData[i] then
            KTool.SetActive(v.controller.gameObject,true)

            local haveNum = GoodsUtils.GetThingNo(self.constData[i].goodsId)
            local color = haveNum >= self.constData[i].num and "<color=#5C5C5C>%s</color>" or "<color=#e71f55>%s</color>"
            v:SetCurrencyShow(self.constData[i].goodsId,string.format(color,self.constData[i].num))
        else
            KTool.SetActive(v.controller.gameObject,false)
        end
    end
end

function OverseaRenovaInventoryPopup:RefreshGridShow()
    if not self.ScrollView.IsListViewInit then
        self.ScrollView:InitGridView(#self.allData, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ScrollView, #self.allData)
    end
end

function OverseaRenovaInventoryPopup:OnGetItemByIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end

    if #self.allData < (index + 1) then
        return nil
    end

    local cell = listView:NewListViewItem(Cell)
    if not isNull(cell) then
        local env = CfUtils.GetLuaScr(cell,InventoryCellPath)
        if env then
            local data = self.allData[index + 1]
            env:SetCallBack(Bind(self,self.OnToggleCallBack))
            env:RefreshShow(data,self.curIndex,index + 1)
        end
    end
    return cell
end

function OverseaRenovaInventoryPopup:OnToggleCallBack(index)
    self:CalculationDisCount()
    self:RefreshGridShow()
    self:RefreshPriceShow()
end

function OverseaRenovaInventoryPopup:OnBtnCloseClick()
    UIModule.CloseDialog(self.controller)
end

function OverseaRenovaInventoryPopup:OnBtnBuyClick()
    local avatarIds
    for i, v in pairs(self.allData) do
        if not v.isCanDoSelect then
            local isHave = component:IsHaveRenovated(v.data.refId)
            if not isHave then
                if isNull(avatarIds) then
                    avatarIds = v.data.refId
                else
                    avatarIds = table.concat({avatarIds,",",v.data.refId})
                end
            end
        else
            if v.isSelect then
                local isHave = component:IsHaveRenovated(v.data.refId)
                if not isHave then
                    if isNull(avatarIds) then
                        avatarIds = v.data.refId
                    else
                        avatarIds = table.concat({avatarIds,",",v.data.refId})
                    end
                end
            end
        end
    end

    if isNull(avatarIds) then
        GameUtils.Toast(localize("请至少选择一个家具"))
        return
    end

    local buyFunc = function()
        if not isNull(avatarIds) then
            GameUtils.Request(Interfaces.MaidCoffeeAvatarBuy,{avatars = tostring(avatarIds)},function(request,response)
                if checkNumber(response.errCode) == 0 then
                    local data = response.data
                    GoodsUtils.ConsumeGoods(data.consume)
                    ---把自己关了
                    self:OnBtnCloseClick()
                    if #data.rewards > 0 then
                        GoodsUtils.DrawRewards(data.rewards)
                        UIModule.OpenDialog(
                                {
                                    id = Constants.UITypeIds.UICommonRewardPop,
                                    parameters = { rewards = data.rewards, cb = function() end }
                                }
                        )
                    end
                    if self.parameters.cb then
                        self.parameters.cb()
                    end
                end
            end)
        end
    end

    local isMoneyEnough = self:IsHaveEnoughMoney()
    if not isMoneyEnough then
        GoodsUtils.CheckCurrencyConsume(self.constData[1], buyFunc,{{id = Constants.UITypeIds.OverseaRenovaListDialog }})
        return
    end
    buyFunc()
end

function OverseaRenovaInventoryPopup:IsHaveEnoughMoney()
    local isEnough = true
    for i, v in pairs(self.constData) do
        local enough = GoodsUtils.GetThingNo(v.goodsId) >= v.num
        if not enough then
            isEnough = false
            break
        end
    end
    return isEnough
end

return OverseaRenovaInventoryPopup